{
  "name": "<%= appName %>",
  "version": "1.0.0",
  "private": true,
  "dependencies": {
    "react": "^18.2.0",
    "react-dom": "^18.2.0",
    "react-scripts": "5.0.1"
  },
  "scripts": {
    "start": "react-scripts start",
    "build": "react-scripts build",
    "test": "react-scripts test",
    "eject": "react-scripts eject"
  }
}

import { Entity, PrimaryGeneratedColumn, Column, CreateDateColumn, UpdateDateColumn } from 'typeorm';

@Entity('<%= tableName %>')
export class <%= className %> {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Column()
  name!: string;

  @CreateDateColumn()
  createdAt!: Date;

  @UpdateDateColumn()
  updatedAt!: Date;
}

name: Scheduled Tasks

on:
  schedule:
    # Run daily at 2 AM UTC
    - cron: '0 2 * * *'
    # Run weekly on Sundays at 3 AM UTC
    - cron: '0 3 * * 0'
  workflow_dispatch:

jobs:
  dependency-updates:
    name: Check for Dependency Updates
    runs-on: ubuntu-latest
    steps:
    - name: Checkout code
      uses: actions/checkout@v4

    - name: Setup Node.js
      uses: actions/setup-node@v4
      with:
        node-version: '18'
        cache: 'npm'

    - name: Check for outdated dependencies
      run: npm outdated --json > outdated.json || echo '{}' > outdated.json

    - name: Create issue for outdated dependencies
      uses: actions/github-script@v7
      with:
        script: |
          const fs = require('fs');
          const outdated = JSON.parse(fs.readFileSync('outdated.json', 'utf8'));

          if (Object.keys(outdated).length > 0) {
            const body = `## Dependency Updates Available 🔄

            The following dependencies have updates available:

            ${Object.entries(outdated).map(([pkg, info]) => {
              const current = info.current;
              const latest = info.latest;
              return `- **${pkg}**: ${current} → ${latest}`;
            }).join('\n')}

            Please review and update these dependencies when appropriate.`;

            await github.rest.issues.create({
              owner: context.repo.owner,
              repo: context.repo.repo,
              title: 'Dependency Updates Available',
              body: body,
              labels: ['dependencies', 'automated']
            });
          }

  security-audit:
    name: Security Audit
    runs-on: ubuntu-latest
    steps:
    - name: Checkout code
      uses: actions/checkout@v4

    - name: Setup Node.js
      uses: actions/setup-node@v4
      with:
        node-version: '18'
        cache: 'npm'

    - name: Run security audit
      run: npm audit --audit-level=moderate --json > audit.json || echo '{}' > audit.json

    - name: Create issue for security vulnerabilities
      uses: actions/github-script@v7
      with:
        script: |
          const fs = require('fs');
          const audit = JSON.parse(fs.readFileSync('audit.json', 'utf8'));

          if (audit.vulnerabilities && Object.keys(audit.vulnerabilities).length > 0) {
            const body = `## Security Vulnerabilities Found 🚨

            The following security vulnerabilities were detected:

            ${Object.entries(audit.vulnerabilities).map(([pkg, vuln]) => {
              return `- **${pkg}**: ${vuln.title} (${vuln.severity})`;
            }).join('\n')}

            Please review and address these vulnerabilities.`;

            await github.rest.issues.create({
              owner: context.repo.owner,
              repo: context.repo.repo,
              title: 'Security Vulnerabilities Detected',
              body: body,
              labels: ['security', 'automated', 'high-priority']
            });
          }

  performance-monitoring:
    name: Performance Monitoring
    runs-on: ubuntu-latest
    steps:
    - name: Checkout code
      uses: actions/checkout@v4

    - name: Setup Node.js
      uses: actions/setup-node@v4
      with:
        node-version: '18'
        cache: 'npm'

    - name: Install dependencies
      run: npm ci

    - name: Run performance tests
      run: npm run test:performance

    - name: Upload performance results
      uses: actions/upload-artifact@v4
      with:
        name: performance-results
        path: performance-results.json

  cleanup:
    name: Cleanup Old Artifacts
    runs-on: ubuntu-latest
    steps:
    - name: Cleanup old workflow runs
      uses: actions/github-script@v7
      with:
        script: |
          const { data: runs } = await github.rest.actions.listWorkflowRuns({
            owner: context.repo.owner,
            repo: context.repo.repo,
            workflow_id: 'scheduled.yml',
            per_page: 100
          });

          const thirtyDaysAgo = new Date();
          thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

          for (const run of runs.workflow_runs) {
            if (new Date(run.created_at) < thirtyDaysAgo) {
              await github.rest.actions.deleteWorkflowRun({
                owner: context.repo.owner,
                repo: context.repo.repo,
                run_id: run.id
              });
            }
          }
